import{_ as t,o,c as a,ag as n}from"./chunks/framework.em2JOrjF.js";const u=JSON.parse('{"title":"Envelopes","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/allocations.md","filePath":"reference/concepts/allocations.md"}'),s={name:"reference/concepts/allocations.md"};function r(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="allocations" tabindex="-1">Envelopes <a class="header-anchor" href="#allocations" aria-label="Permalink to &quot;Envelopes {#allocations}&quot;">​</a></h1><p>Envelopes are how Managers plan and distribute work. They are a planning tool — they do not gate who can log time.</p><hr><h2 id="what-is-an-envelope" tabindex="-1">What is an envelope? <a class="header-anchor" href="#what-is-an-envelope" aria-label="Permalink to &quot;What is an envelope? {#what-is-an-envelope}&quot;">​</a></h2><p>An <strong>envelope</strong> is a per-person hour budget on a specific project.</p><p>Think of it literally: you have a project with 200 hours in its budget. As a Manager, you put 60 hours in an envelope for Alice, 80 hours for Bob, and 60 hours for Carol. Each person&#39;s envelope is their planned share of the work.</p><ul><li><strong>Alice&#39;s envelope</strong>: 60 hours on Nike Rebrand</li><li><strong>Bob&#39;s envelope</strong>: 80 hours on Nike Rebrand</li><li><strong>Carol&#39;s envelope</strong>: 60 hours on Nike Rebrand</li></ul><p>The underlying data lives in the <code>07. Budgets</code> sheet (despite the sheet name, it stores per-person envelopes, not project budgets). Tool names use &quot;allocation&quot; — e.g. <code>allocate_hours</code>, <code>get_allocations</code> — but the concept is always an envelope.</p><hr><h2 id="envelopes-vs-budgets" tabindex="-1">Envelopes vs. budgets <a class="header-anchor" href="#envelopes-vs-budgets" aria-label="Permalink to &quot;Envelopes vs. budgets&quot;">​</a></h2><p>These two words are often confused. In VERA they mean different things:</p><table tabindex="0"><thead><tr><th>Term</th><th>What it is</th><th>Who sets it</th><th>Where it lives</th></tr></thead><tbody><tr><td><strong>Budget</strong></td><td>Total project hours — the whole pie</td><td>Owner</td><td><code>02. Projects</code>.<code>budget_hours</code></td></tr><tr><td><strong>Envelope</strong></td><td>One person&#39;s slice of that pie</td><td>Manager or Owner</td><td><code>07. Budgets</code></td></tr></tbody></table><blockquote><p><strong>Owners and Managers can have envelopes too.</strong> Any active user — regardless of role — can receive an envelope. An Owner or Manager asking &quot;create an envelope for me on Project X&quot; is a completely valid request. PM assignment and envelopes are separate concerns: being a PM means you manage the project; having an envelope means your hours on that project are tracked against a plan. These are independent.</p></blockquote><p>The sum of all envelopes on a project should not exceed the project&#39;s total budget. VERA will warn you if it does, but it won&#39;t hard-block the creation.</p><hr><h2 id="envelopes-vs-assignments" tabindex="-1">Envelopes vs. assignments <a class="header-anchor" href="#envelopes-vs-assignments" aria-label="Permalink to &quot;Envelopes vs. assignments&quot;">​</a></h2><p>These terms are also used interchangeably in conversation, but they have a precise meaning in VERA:</p><ul><li><strong>Assignment</strong>: the state of having an envelope on a project — i.e. having at least one active envelope row</li><li><strong>Envelope</strong>: the specific record (with an hours amount and optional task tag)</li></ul><p>When someone asks &quot;who is on this project?&quot;, the answer is: everyone with an active envelope.</p><p>When someone asks &quot;what should I work on?&quot;, the answer is: your active envelopes — the projects you have envelopes on, with hours remaining.</p><hr><h2 id="envelopes-do-not-gate-time-logging" tabindex="-1">Envelopes do not gate time logging <a class="header-anchor" href="#envelopes-do-not-gate-time-logging" aria-label="Permalink to &quot;Envelopes do not gate time logging&quot;">​</a></h2><p>This is the most important thing to understand about envelopes:</p><p><strong>Anyone can log time to any active project, regardless of whether they have an envelope.</strong></p><p>Envelopes are a planning and visibility tool. They answer &quot;how was the work supposed to be distributed?&quot; — they are not an access control mechanism.</p><p>If a User logs time to a project they don&#39;t have an envelope on, VERA records it. If they log more hours than their envelope, VERA records it (and flags the overdraw). The system trusts that Managers are monitoring envelopes and responding to alerts.</p><hr><h2 id="envelope-fields" tabindex="-1">Envelope fields <a class="header-anchor" href="#envelope-fields" aria-label="Permalink to &quot;Envelope fields&quot;">​</a></h2><p>Each envelope has:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Permanent sequential ID — use this to update or cancel</td></tr><tr><td><code>user_id</code></td><td>The person this envelope belongs to</td></tr><tr><td><code>project_id</code></td><td>The project it&#39;s for</td></tr><tr><td><code>allocated_hours</code></td><td>Hours budgeted for this person on this project</td></tr><tr><td><code>task_id</code></td><td>Optional: work category tag (links to a task type)</td></tr><tr><td><code>status</code></td><td><code>active</code> or <code>cancelled</code></td></tr><tr><td><code>created_by</code></td><td>Manager or Owner who created the envelope</td></tr><tr><td><code>created_at</code></td><td>Date created</td></tr></tbody></table><p>The optional <code>task_id</code> tag is <strong>not</strong> a constraint on what tasks the person can log — it&#39;s metadata saying &quot;this envelope is intended for Design work&quot; (or whichever task type). It helps with estimates-vs-actuals breakdowns.</p><hr><h2 id="lifetime-envelopes" tabindex="-1">Lifetime envelopes <a class="header-anchor" href="#lifetime-envelopes" aria-label="Permalink to &quot;Lifetime envelopes&quot;">​</a></h2><p>Envelopes are not weekly or monthly — they are a project-lifetime budget. An envelope of 160 hours doesn&#39;t mean 160 hours this week; it means 160 hours in total on that project.</p><p>VERA tracks how many of those hours have been logged and how many remain.</p><hr><h2 id="budget-overdraw" tabindex="-1">Budget overdraw <a class="header-anchor" href="#budget-overdraw" aria-label="Permalink to &quot;Budget overdraw&quot;">​</a></h2><p>When a person has logged more hours than their allocated budget on a project, that is a <strong>budget overdraw</strong>.</p><p>VERA surfaces overdraws in morning and evening summaries, and via <code>get_estimates_vs_actuals</code>. A delta &gt; 0 means over-plan. Example:</p><blockquote><p>&quot;⚠️ Bob has logged 45h on Nike Rebrand but only has 40h in his envelope — 5h over.&quot;</p></blockquote><p>Overdraw doesn&#39;t block logging. It&#39;s a signal for the Manager to either update the envelope or have a scope conversation with the client.</p><hr><h2 id="capacity-and-overbooking" tabindex="-1">Capacity and overbooking <a class="header-anchor" href="#capacity-and-overbooking" aria-label="Permalink to &quot;Capacity and overbooking&quot;">​</a></h2><p><strong>Team availability</strong> is the aggregate view: for each person, how many hours are they allocated vs. how many are free.</p><p><strong>Overbooking</strong> happens when a person&#39;s total envelopes across all their projects exceed their available capacity.</p><p><strong>How capacity is calculated:</strong></p><p>VERA calculates available capacity from two sources: the user&#39;s individual <code>hours_per_week</code> setting, and the calendar. The formula is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>available hours = (working days × hours_per_day) − company holidays − time off</span></span>
<span class="line"><span></span></span>
<span class="line"><span>where: hours_per_day = user.hours_per_week ÷ work_days_per_week</span></span></code></pre></div><p>Time-off hours (sick, leave, PTO) are capped at the user&#39;s <code>hours_per_day</code> per entry. This ensures a sick day logged at a standard 8-hour block doesn&#39;t over-subtract from a contractor whose working day is shorter.</p><p><strong><code>hours_per_week</code> is set per person:</strong></p><ul><li><strong>FTE</strong>: defaults to 40. No need to specify when adding a user.</li><li><strong>Contractor</strong>: must be set explicitly when adding the user. A contractor doing 3 days a week at standard hours would be 24. VERA will ask for this when you add a contractor.</li><li><strong>Vendor</strong>: placeholder value of 40. Vendor capacity is not tracked meaningfully — cost is governed by liabilities, not hours.</li></ul><p>The work week schedule (which days count, and how many hours per day for the base calculation) is configured at the tenant level via <code>set_work_week</code>, defaulting to Mon–Fri. Company holidays from <code>12. Company_Calendar</code> and approved time off already logged are both subtracted.</p><p>The overbooking check uses a rolling <strong>90-day window</strong> from today. This means capacity is compared against available working time in the next 3 months, not against a single day or week.</p><p>VERA detects overbooking when you create or update an envelope via <code>allocate_hours</code>. If the envelope would put someone over capacity in the 90-day window, VERA returns <code>overbooked: true</code> and flags the person and hours over. This doesn&#39;t block the creation — it&#39;s a warning.</p><p>Use <code>get_team_availability</code> to see everyone&#39;s headroom across all projects. Use <code>check_capacity</code> when evaluating whether the team can take on new work.</p><hr><h2 id="envelope-lifecycle" tabindex="-1">Envelope lifecycle <a class="header-anchor" href="#envelope-lifecycle" aria-label="Permalink to &quot;Envelope lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allocate_hours → active envelope</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>update_allocation → change hours (up or down)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>cancel_allocation → envelope marked cancelled (not deleted)</span></span></code></pre></div><p>Cancelled envelopes are kept for audit trail purposes. When you query envelopes, VERA returns only active ones by default.</p><hr><h2 id="common-envelope-queries" tabindex="-1">Common envelope queries <a class="header-anchor" href="#common-envelope-queries" aria-label="Permalink to &quot;Common envelope queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Tool</th></tr></thead><tbody><tr><td>&quot;What should I work on?&quot;</td><td><code>get_my_assignments</code></td></tr><tr><td>&quot;What are Alice&#39;s envelopes?&quot;</td><td><code>get_person_allocation_summary</code></td></tr><tr><td>&quot;Who is on the Nike project?&quot;</td><td><code>get_project_assignments</code></td></tr><tr><td>&quot;How much headroom does the team have?&quot;</td><td><code>get_team_availability</code></td></tr><tr><td>&quot;How did plan vs actual compare last week?&quot;</td><td><code>get_estimates_vs_actuals</code></td></tr><tr><td>&quot;Can we take on new work in April?&quot;</td><td><code>check_capacity</code></td></tr><tr><td>&quot;What&#39;s the 4-week capacity outlook?&quot;</td><td><code>get_capacity_forecast</code></td></tr></tbody></table>`,62)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
